import{_ as i,l as d,o as a,c as n,v as r,p as l,x as o,d as s,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"无锁栈与 hazard pointer","description":"","frontmatter":{"title":"无锁栈与 hazard pointer","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hazard-pointer.md","filePath":"cs/hazard-pointer.md","lastUpdated":1789023840000}'),p={name:"cs/hazard-pointer.md"};function A(E,e,m,P,_,B){const t=d("Mermaid");return a(),n("div",null,[e[1]||(e[1]=r('<h1 id="无锁栈与-hazard-pointer" tabindex="-1">无锁栈与 hazard pointer <a class="header-anchor" href="#无锁栈与-hazard-pointer" aria-label="Permalink to &quot;无锁栈与 hazard pointer&quot;">​</a></h1><div class="epigraph"><p>Treiber 栈用 CAS 换头，ABA 几乎是默认陷阱。Hazard pointer：读者先公布「我正抓着这些指针」，回收者跳过仍被抓的节点。</p><footer>—— 据 Treiber, Systems Programming: Coping with Parallelism, IBM 1986；Michael, Hazard Pointers: Safe Memory Reclamation for Lock-Free Objects, IEEE TPDS 2004 整理</footer></div><p><a href="/cs/michael-scott-queue">上一课</a> 留下节点何时 <code>free</code>。<a href="/cs/lockfree-aba">无锁与 ABA</a> 已给现象。<a href="/cs/rcu-gp">RCU 宽限期</a> 是另一回收。本课不重讲 dummy 节点。缺口是 Treiber 栈 + hazard pointer 回收合同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>栈：<code>head</code> 指向单链。push：新节点 <code>next=head</code>，CAS <code>head</code>。pop：读 <code>h</code>，CAS <code>head</code> 到 <code>h-&gt;next</code>。ABA：pop 读 next 后，<code>h</code> 被弹出再压回，CAS 仍成功但 next 陈旧。hazard：线程进入临界前把指针写入 HP 槽并屏障，扫描时若节点出现在任一 HP 中则延后释放。缺口是<strong>把「还在被读的地址」显式登记</strong>，而不靠停全世界。</p><p><span class="marginnote">Treiber 1986 技术报告。Michael, <em>IEEE Trans. Parallel and Dist. Systems</em>, 2004（PODC 2004 前身）。epoch/QSBR 是批量版，RCU 课已见。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每线程少量 HP 槽（栈 pop 常 1–2 个）。退休列表攒一批再扫描 HP。漏登记 = UAF；多登记只延迟回收。与带 tag 的双字 CAS：tag 防 ABA 但不防 UAF，常要两者或再加池。</p>',8)),(a(),l(h,null,{default:o(()=>[c(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20POP%5B%22pop%20%E8%AF%BB%20head%22%5D%20--%3E%20HP%5B%22%E5%86%99%E5%85%A5%20hazard%20%E6%A7%BD%22%5D%0A%20%20HP%20--%3E%20CAS%5B%22CAS%20%E6%8D%A2%E5%A4%B4%22%5D%0A%20%20RET%5B%22%E9%80%80%E4%BC%91%E8%8A%82%E7%82%B9%22%5D%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%E5%85%A8%E9%83%A8%20HP%22%5D%0A%20%20SCAN%20--%3E%20FREE%5B%22%E6%9C%AA%E5%91%BD%E4%B8%AD%E5%88%99%E5%8F%AF%E9%87%8A%E6%94%BE%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>与 MS 队列：同样需要 HP 或 epoch 保护 <code>head/tail/next</code>。与 RCU：RCU 读侧更轻、写侧等宽限期；HP 读侧要写槽。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>进度：扫描 HP 是回收者的活，读者无锁。槽要避免伪共享。本课不写攻击性 UAF exploit。并发哈希表下一课把桶锁或无锁探针对上字典，不是栈。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 SMR（EBR、HE、PEBR）列成百科。实时最坏扫描 HP 与线程数有关。有序/无序字典的并发下一课。</p><p>后课默认：无锁链表回收用 HP 或 epoch。并发映射用分段锁或无锁桶。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Treiber 栈：CAS 头；ABA 与回收绑定。</li><li>Hazard pointer：公布指针，退休时扫描。</li><li>下一课并发哈希表。</li><li>出处：Treiber, 1986；Michael, <em>TPDS</em>, 2004。</li></ul>',8))])}const f=i(p,[["render",A]]);export{u as __pageData,f as default};
